UPDATE `creaturemodeldata` SET `size_class` = 1, `model_scale` = 1, `collision_width` = 0.6111, `collision_height` = 2.031, `mount_height` = 1.50425, `geo_box_min_x` = -0.958703, `geo_box_min_y` = -0.666762, `geo_box_min_z` = 0.006144, `geo_box_max_x` = 0.902441, `geo_box_max_y` = 0.732732, `geo_box_max_z` = 2.63229, `world_effect_scale` = 1, `attached_effect_scale` = 1, `missile_collision_radius` = 0, `missile_collision_push` = 0, `missile_collision_raise` = 0 WHERE `id` = @SethrakMaleModel;
